<?php
class Reporte_ocupacion_model extends CI_Model{
    public function usuario_tiene_rol($usuario_id,$rol_id){$r=$this->db->query("SELECT 1 ok FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$usuario_id,(int)$rol_id))->row_array();return !empty($r);}
    public function listas(){return array('rutas'=>$this->db->query("SELECT ruta_id,ruta_nombre,inicio_ruta,fin_ruta FROM ruta ORDER BY ruta_nombre")->result_array(),'vehiculos'=>$this->db->query("SELECT vehiculo_id,vehiculo_placa,vehiculo_marca,vehiculo_modelo FROM vehiculo ORDER BY vehiculo_placa")->result_array());}
    public function ocupacion($f){
        $expr=array('ruta'=>"CONCAT_WS(' - ',COALESCE(r.inicio_ruta,r.ruta_nombre),r.fin_ruta)",'horario'=>"DATE_FORMAT(v.viaje_horasalida,'%H:%i')",'vehiculo'=>"CONCAT(COALESCE(ve.vehiculo_placa,''),' ',COALESCE(ve.vehiculo_marca,''),' ',COALESCE(ve.vehiculo_modelo,''))",'dia_semana'=>"ELT(DAYOFWEEK(v.viaje_fechasalida),'DOMINGO','LUNES','MARTES','MIÉRCOLES','JUEVES','VIERNES','SÁBADO')",'mes'=>"DATE_FORMAT(v.viaje_fechasalida,'%Y-%m')");
        $g=$expr[$f['grupo']]; $where="v.viaje_fechasalida BETWEEN ? AND ?"; $par=array($f['desde'],$f['hasta']); if($f['ruta_id']>0){$where.=" AND v.ruta_id=?";$par[]=$f['ruta_id'];} if($f['vehiculo_id']>0){$where.=" AND v.vehiculo_id=?";$par[]=$f['vehiculo_id'];}
        // Capacidad se calcula por viaje desde asientos realmente visibles/vendibles, con fallback al vehículo.
        $sql="SELECT X.grupo,COUNT(*) viajes,SUM(X.capacidad) capacidad,SUM(X.vendidos) vendidos,SUM(X.reservados) reservados,GREATEST(SUM(X.capacidad)-SUM(X.vendidos)-SUM(X.reservados),0) disponibles,CASE WHEN SUM(X.capacidad)>0 THEN SUM(X.vendidos)*100.0/SUM(X.capacidad) ELSE 0 END ocupacion,SUM(X.venta_neta) venta_neta FROM (SELECT v.viaje_id,$g grupo,COALESCE(NULLIF((SELECT COUNT(*) FROM asientos a WHERE a.vehiculo_id=v.vehiculo_id AND a.asiento_mostrar=1 AND a.asiento_es_vendible=1),0),NULLIF(ve.vehiculo_asientos,0),NULLIF(ve.vehiculo_pasajeros,0),0) capacidad,(SELECT COUNT(*) FROM pasaje p WHERE p.viaje_id=v.viaje_id AND p.estado_id=54) vendidos,(SELECT COUNT(*) FROM pasaje p WHERE p.viaje_id=v.viaje_id AND p.estado_id=52) reservados,(SELECT COALESCE(SUM(vp.venta_total),0) FROM venta_pasaje vp WHERE vp.viaje_id=v.viaje_id AND vp.estado_id=1) venta_neta FROM viaje v LEFT JOIN ruta r ON r.ruta_id=v.ruta_id LEFT JOIN vehiculo ve ON ve.vehiculo_id=v.vehiculo_id WHERE $where) X GROUP BY X.grupo ORDER BY ocupacion DESC,X.grupo";
        return $this->db->query($sql,$par)->result_array();
    }
}
